:root {
  /* Colors */
  --color-fog-canvas: #f5f5f5;
  --color-concrete-panel: #efefef;
  --color-paper-white: #ffffff;
  --color-mist-tile: #e8e8e8;
  --color-linen-sand: #ebe6dd;
  --color-ink: #202020;
  --color-graphite-body: #4d4d4d;
  --color-pewter-caption: #828282;
  --color-brass-signal: #816729;
  --color-ember-spark: #ff682c;
  --color-umber-panel: #3c1e1a;
  --color-cobalt-badge: #0064b5;

  /* Typography — Font Families */
  --font-polysans: "PolySans", "Schibsted Grotesk", "Hanken Grotesk", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", "Roboto Flex", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.33;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.38;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.33;
  --tracking-body-lg: 0px;
  --text-heading: 32px;
  --leading-heading: 1.19;
  --tracking-heading: -0.64px;
  --text-heading-lg: 40px;
  --leading-heading-lg: 1.2;
  --tracking-heading-lg: -0.8px;
  --text-display: 66px;
  --leading-display: 0.91;
  --tracking-display: -1.32px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-13: 13px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-30: 30px;
  --spacing-40: 40px;
  --spacing-50: 50px;
  --spacing-60: 60px;
  --spacing-70: 70px;
  --spacing-80: 80px;
  --spacing-85: 85px;
  --spacing-120: 120px;
  --spacing-140: 140px;

  /* Layout */
  --layout-gutter: 120px;
  --layout-rail: 80px;
  --layout-measure: 662px;
  --layout-measure-sm: 500px;
  --layout-section-gap: 120px;
  --layout-card-padding: 40px;
  --layout-element-gap: 20px;

  /* Border Radius */
  --radius-sm: 3px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 20px;
  --radius-full: 200px;

  /* Named Radii */
  --radius-cards: 8px 0px 0px 8px;
  --radius-inner-tiles: 8px;
  --radius-tags: 6px 0px 0px 0px;
  --radius-small-elements: 3px;
  --radius-small-cards: 12px;
  --radius-buttons: 20px;
  --radius-sections: 20px;
  --radius-nav: 200px;
  --radius-images: 0px;

  /* Shadows */
  --shadow-none: none;

  /* Surfaces */
  --surface-fog-canvas: #f5f5f5;
  --surface-concrete-panel: #efefef;
  --surface-linen-sand: #ebe6dd;
  --surface-paper-white: #ffffff;
  --surface-ink: #202020;
}

